package com.nexamart.backend.domain;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Order order;@ManyToOne(optional=false)private Product product;private String productName;private BigDecimal unitPrice;private int quantity;private BigDecimal lineTotal;public Long getId(){return id;}public Order getOrder(){return order;}public void setOrder(Order v){order=v;}public Product getProduct(){return product;}public void setProduct(Product v){product=v;}public String getProductName(){return productName;}public void setProductName(String v){productName=v;}public BigDecimal getUnitPrice(){return unitPrice;}public void setUnitPrice(BigDecimal v){unitPrice=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}public BigDecimal getLineTotal(){return lineTotal;}public void setLineTotal(BigDecimal v){lineTotal=v;}}
